import time

from app import security
from app.db import get_db
from tests.conftest import csrf_token


# ---- US-101 Registration -------------------------------------------------

def test_register_page_has_required_fields(client):
    html = client.get("/auth/register").get_data(as_text=True)
    for field in ('name="username"', 'name="email"', 'name="password"'):
        assert field in html
    assert "required" in html and 'minlength="8"' in html


def test_register_success_redirects_to_login(actions):
    response = actions.register()
    assert response.status_code == 302
    assert response.headers["Location"].endswith("/auth/login")


def test_register_password_is_hashed(app, actions):
    actions.register(password="password123")
    with app.app_context():
        row = get_db().execute("SELECT password_hash FROM user").fetchone()
    assert row["password_hash"] != "password123"
    assert "password123" not in row["password_hash"]


def test_register_validation_errors(actions):
    cases = [
        {"username": "", "email": "a@example.com", "password": "password123"},
        {"username": "alice", "email": "", "password": "password123"},
        {"username": "alice", "email": "a@example.com", "password": ""},
        {"username": "alice", "email": "a@example.com", "password": "short"},
        {"username": "alice", "email": "a@example.com", "password": "x" * 129},
        {"username": "al", "email": "a@example.com", "password": "password123"},
        {"username": "bad name", "email": "a@example.com", "password": "password123"},
        {"username": "alice", "email": "not-an-email", "password": "password123"},
    ]
    for data in cases:
        assert actions.post("/auth/register", data).status_code == 400, data


def test_register_rejects_username_containing_at_sign(actions):
    response = actions.register(username="victim@example.com", email="attacker@example.com")
    assert response.status_code == 400


def test_register_duplicate_username_case_insensitive(actions):
    actions.register("alice", "alice@example.com")
    response = actions.register("ALICE", "other@example.com")
    assert response.status_code == 400
    assert "already taken" in response.get_data(as_text=True)


def test_register_duplicate_email_case_insensitive(actions):
    actions.register("alice", "alice@example.com")
    response = actions.register("bob", "ALICE@Example.com")
    assert response.status_code == 400
    assert "already registered" in response.get_data(as_text=True)


# ---- US-102 Login --------------------------------------------------------

def test_login_by_username_redirects_home(actions):
    actions.register()
    response = actions.login("alice")
    assert response.status_code == 302
    assert response.headers["Location"].endswith("/")


def test_login_by_email_case_insensitive(actions):
    actions.register()
    assert actions.login("ALICE@example.com").status_code == 302


def test_login_invalid_credentials_same_message(actions):
    actions.register()
    wrong_password = actions.login("alice", "wrongpassword")
    unknown_user = actions.login("nobody", "password123")
    assert wrong_password.status_code == unknown_user.status_code == 401
    msg = "Invalid username/email or password."
    assert msg in wrong_password.get_data(as_text=True)
    assert msg in unknown_user.get_data(as_text=True)


def test_login_page_has_fields(client):
    html = client.get("/auth/login").get_data(as_text=True)
    assert 'name="identifier"' in html and 'name="password"' in html


def test_logged_in_user_redirected_away_from_login_and_register(make_client):
    client, _ = make_client()
    assert client.get("/auth/login").status_code == 302
    assert client.get("/auth/register").status_code == 302


# ---- US-103 Session & logout --------------------------------------------

def test_unauthenticated_home_redirects_to_login(client):
    response = client.get("/")
    assert response.status_code == 302
    assert "/auth/login" in response.headers["Location"]


def test_session_persists_across_requests(make_client):
    client, _ = make_client()
    assert client.get("/").status_code == 200
    assert client.get("/").status_code == 200


def test_logout_button_visible_and_ends_session(make_client):
    client, actions = make_client()
    assert "Logout" in client.get("/").get_data(as_text=True)
    response = actions.logout()
    assert response.status_code == 302
    assert response.headers["Location"].endswith("/auth/login")
    assert client.get("/").status_code == 302


def test_session_expires_after_30_minutes_of_inactivity(make_client, monkeypatch):
    client, _ = make_client()
    start = time.time()
    monkeypatch.setattr(security, "now", lambda: start + 31 * 60)
    response = client.get("/")
    assert response.status_code == 302
    assert "/auth/login" in response.headers["Location"]
    monkeypatch.setattr(security, "now", lambda: start + 31 * 60 + 1)
    assert client.get("/").status_code == 302


def test_expired_session_shows_flash_message_on_login_page(make_client, monkeypatch):
    client, _ = make_client()
    monkeypatch.setattr(security, "now", lambda: time.time() + 31 * 60)
    response = client.get("/", follow_redirects=True)
    assert "Your session expired" in response.get_data(as_text=True)


def test_register_success_shows_flash_on_login_page(actions):
    response = actions.register()
    page = actions.client.get(response.headers["Location"]).get_data(as_text=True)
    assert "Account created" in page


def test_session_valid_just_under_timeout(make_client, monkeypatch):
    client, _ = make_client()
    monkeypatch.setattr(security, "now", lambda: time.time() + 29 * 60)
    assert client.get("/").status_code == 200


def test_activity_extends_session(make_client, monkeypatch):
    client, _ = make_client()
    start = time.time()
    monkeypatch.setattr(security, "now", lambda: start + 20 * 60)
    assert client.get("/").status_code == 200
    monkeypatch.setattr(security, "now", lambda: start + 40 * 60)
    assert client.get("/").status_code == 200


def test_keepalive_refreshes_session(make_client):
    client, _ = make_client()
    response = client.post("/auth/keepalive", headers={"X-CSRF-Token": csrf_token(client)})
    assert response.status_code == 204


def test_keepalive_expired_returns_401(make_client, monkeypatch):
    client, _ = make_client()
    token = csrf_token(client)
    monkeypatch.setattr(security, "now", lambda: time.time() + 31 * 60)
    response = client.post("/auth/keepalive", headers={"X-CSRF-Token": token})
    assert response.status_code == 401
